svg.script:
var chip = {

  menu: {
    'Value +1': {
      eventName: 'value_incr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        chip.increment(this, 1)
      },
    },
    'Value -1': {
      eventName: 'value_decr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        chip.increment(this, -1)
      },
    },
    'Stack': {
      eventName: 'chip_stack',
      otherEvents: ['dblclick'],
      applicable: (node) => chip.stack_applicable(node),
      handler: function(evt) {
        console.warn('TODO')
      },
    },
  },

  stack_applicable: function(elem) {
    if (elem.getAttribute('data-above') || elem.getAttribute('data-below')) {
      return true
    } else {
      return false
    }
  },

  increment: function(elem, step) {
    const tspan = elem.querySelector('tspan')
    const current = parseInt(tspan.textContent)
    tspan.textContent = String(current + step)
  },

  on_position_occupied: function(elem, posId, ownerId, movingId) {
    elem.setAttribute('data-below', movingId)
  },

  on_position_vacated: function(elem, posId, ownerId, movingId) {
    elem.setAttribute('data-below', '')
  },

  on_arrive_position: function(elem, posId, ownerId) {
    elem.setAttribute('data-above', ownerId)
  },

  on_depart_position: function(elem, posId, ownerId) {
    elem.setAttribute('data-above', '')
  },

}
